/** Follow-up suggestion chips (≤ 4, Persian, ≤ 6 words each) generated by the fast model. */
import { z } from 'zod';
import { callSettings, safeGenerateObject } from './providers';
import type { AgentRuntime } from './runtime';

const ChipsSchema = z.object({ chips: z.array(z.string()).max(6) });

export function cleanChips(chips: string[]): string[] {
  const seen = new Set<string>();
  return chips
    .map((c) => c.replace(/^[-•\d.\s«"]+|[»".]+$/g, '').trim())
    .filter((c) => c.length >= 3 && c.split(/\s+/).length <= 7 && !seen.has(c) && (seen.add(c), true))
    .slice(0, 4);
}

export async function suggestChips(rt: AgentRuntime, lastAssistantText: string, appName?: string): Promise<string[]> {
  if (!lastAssistantText.trim()) return [];
  const { object } = await safeGenerateObject({
    model: rt.model('fast'),
    schema: ChipsSchema,
    schemaName: 'suggestions',
    system: 'You write follow-up suggestion chips for a Persian DevOps assistant chat. Output Persian only.',
    prompt: [
      `آخرین پاسخ دستیار:\n${lastAssistantText.slice(-1500)}`,
      '',
      `حداکثر ۴ پیشنهاد کوتاه بنویس که کاربر بتواند همان را به‌عنوان پیام بعدی بفرستد${appName ? ` (سرویس فعلی: ${appName})` : ''}.`,
      'هر پیشنهاد حداکثر ۶ کلمه، فارسی ساده، عملی و مرتبط با همین گفت‌وگو؛ مثل «لاگ‌های خطا را نشان بده» یا «پایش خودکار را روشن کن». واژه‌ی انگلیسی ننویس (به‌جای rollback بگو «برگرد به نسخه‌ی قبلی»). اگر پیشنهاد مفیدی نیست آرایه‌ی خالی بده.',
    ].join('\n'),
    timeoutMs: 20_000,
    maxOutputTokens: 400,
    ...callSettings('fast', rt.deps.config, 0.5),
  });
  return cleanChips(object.chips);
}
